'use client';
import React,{useState,useEffect,useLayoutEffect,useMemo,useRef,useCallback} from 'react';
import {ArrowUpRight,ArrowRight,ArrowLeft,Plus,Minus,Search,Sparkles,SlidersHorizontal,Upload,Download,Check,CheckCheck,X,Menu,ShoppingBag,Layers,Type,Image as ImageIcon,Square,RotateCcw,RotateCw,Trash2,Copy,ZoomIn,ZoomOut,Move,Eye,Grid2X2,LayoutTemplate,Palette,Package,Truck,Clock,FileCheck2,FolderOpen,MoreHorizontal,ChevronDown,ChevronRight,Settings2,Command as CommandIcon,MapPin,ExternalLink,ShieldCheck,Code2,Link2,Send,Info,AlertTriangle,Printer,Box,Scissors,BookOpen,Shirt,Star,Globe,ClipboardList,BarChart3,Save,MousePointer2,Lock,Play,Activity,CheckCircle2,Circle,FileJson} from 'lucide-react';
import {Dialog,DialogContent,DialogTitle,DialogDescription,DialogHeader} from '@/components/ui/dialog';
import {Sheet,SheetContent,SheetTitle,SheetDescription,SheetHeader} from '@/components/ui/sheet';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Select,SelectTrigger,SelectContent,SelectItem,SelectValue} from '@/components/ui/select';
import {Slider} from '@/components/ui/slider';
import {Switch} from '@/components/ui/switch';
import {Progress} from '@/components/ui/progress';
import {Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '@/components/ui/table';
import {Command,CommandInput,CommandList,CommandEmpty,CommandGroup,CommandItem} from '@/components/ui/command';
import {DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger} from '@/components/ui/dropdown-menu';
import {Toaster} from '@/components/ui/sonner';
import {toast} from 'sonner';
import {products,categories,money,calculateQuote,finishesFor,initialDesign,templates,competitorRows,suppliers,Product,Design,DesignLayer,Tier,QuoteInput} from '@/lib/presswerk/catalog';

import Account from './account';
import {designFingerprint as fingerprint} from '@/lib/presswerk/design-identity';
import WorkspaceSettings from './workspace-settings';
import {useCloudWorkspace} from '@/lib/presswerk/use-cloud-workspace';
import {hydrateDesign,saveCloudProject,approveCloudProof,saveCloudBrand,submitCloudOrder,transitionOrder,orderHistory,authHeaders,cloud,type CloudOrder} from '@/lib/presswerk/cloud';

type View='discover'|'studio'|'projects'|'production'|'pricing'|'brand'|'network'|'developers'|'roadmap'|'settings';
type Order={id:string;name:string;productId:string;quantity:number;total:number;status:string;city:string;date:string;example?:boolean;projectId?:string;version?:number};
type Brand={name:string;tagline:string;primary:string;secondary:string;accent:string;font:string};
const navs:[View,string,React.ElementType][]=[['discover','Discover',Grid2X2],['studio','Design studio',Layers],['projects','My workspace',FolderOpen],['production','Production',Printer],['pricing','Pricing intelligence',BarChart3],['brand','Brand centre',Palette],['network','Supplier network',Globe],['developers','Developer platform',Code2],['roadmap','Launch roadmap',ClipboardList],['settings','Team & API access',Settings2]];
const exampleOrders:Order[]=[{id:'SAMPLE-1042',name:'Off Script / launch collection',productId:'tee',quantity:24,total:581.4,status:'Artwork review',city:'Calgary',date:'2026-09-14',example:true},{id:'SAMPLE-1041',name:'Fieldwork / stationery',productId:'cards',quantity:500,total:29.95,status:'Ready to produce',city:'Calgary',date:'2026-09-15',example:true},{id:'SAMPLE-1040',name:'Northline / autumn exhibition',productId:'poster',quantity:12,total:210,status:'Printing',city:'St. John’s',date:'2026-09-16',example:true},{id:'SAMPLE-1039',name:'The daily ritual / mugs',productId:'mug',quantity:36,total:430.2,status:'Finishing',city:'St. John’s',date:'2026-09-16',example:true}];
const statuses=['Artwork review','Ready to produce','Printing','Finishing','Dispatched'];
function download(data:string,name:string,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function imageSrc(name:string){return (typeof window!=='undefined'&&(window as Window & {__PRESSWERK_ASSETS__?:Record<string,string>}).__PRESSWERK_ASSETS__?.[name])||'/print-app/images/'+name+'.jpg';}
function Pick({value,onChange,options,label}:{value:string;onChange:(v:string)=>void;options:string[];label:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger className="pw-select" aria-label={label}><SelectValue/></SelectTrigger><SelectContent>{options.map(x=><SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent></Select>;}
function Chip({children,color=''}:{children:React.ReactNode;color?:string}){return <span className={'chip '+color}>{children}</span>;}
function formatDate(date:string){return new Date(date).toLocaleDateString('en-CA',{month:'short',day:'numeric'});}
function ProductImage({p,className=''}:{p:Product;className?:string}){return <div className={'product-image '+className}><img src={imageSrc(p.image)} alt={p.image==='cards'?'Printed business cards with cobalt blue and white designs':p.image==='merch'?'Custom printed apparel, tote and mug':'A collection of custom printed products'} loading="lazy"/><span className="product-method">{p.method}</span></div>;}

export default function Presswerk(){
 const [view,setView]=useState<View>('discover');const [design,setDesign]=useState<Design>(()=>initialDesign());const [projects,setProjects]=useState<Design[]>([]);const [orders,setOrders]=useState<Order[]>([]);const [brand,setBrand]=useState<Brand>({name:'Avalon Print',tagline:'Make your mark.',primary:'#2449f8',secondary:'#171719',accent:'#c6ee48',font:'Arial'});
 const [searchOpen,setSearchOpen]=useState(false);const [mobileOpen,setMobileOpen]=useState(false);const [cartOpen,setCartOpen]=useState(false);const [advisorOpen,setAdvisorOpen]=useState(false);const [brief,setBrief]=useState('');const [advice,setAdvice]=useState('');const [busy,setBusy]=useState(false);const [server,setServer]=useState({storage:false,ai:false});const [cart,setCart]=useState<{key:string;design:Design;quote:ReturnType<typeof calculateQuote>}[]>([]);
 const proofTarget=useRef<Design|null>(null);const designRef=useRef(design);const guestDraft=useRef<{design:Design;cart:typeof cart}|null>(null);const cartRef=useRef(cart);
 const [accountOpen,setAccountOpen]=useState(false);const [saving,setSaving]=useState(false);const saveLock=useRef(false);const projectsRef=useRef(projects);
 useLayoutEffect(()=>{designRef.current=design;cartRef.current=cart;projectsRef.current=projects;},[design,cart,projects]);
 const toOrder=(o:CloudOrder):Order=>({id:o.id,name:o.estimate.projectName||o.estimate.product?.name||'Print project',productId:o.estimate.product?.id||'cards',quantity:o.estimate.quantity||1,total:o.estimate.total||0,status:o.status,city:o.estimate.city||'Calgary',date:o.created_at,projectId:o.project_id,version:o.version});
 const account=useCloudWorkspace(data=>{setProjects(data.projects);projectsRef.current=data.projects;setOrders(data.orders.map(toOrder));setBrand(data.workspace.brand);if(guestDraft.current){setDesign(guestDraft.current.design);setCart(guestDraft.current.cart);guestDraft.current=null;}},reason=>{if(reason==='signin'){guestDraft.current={design:designRef.current,cart:cartRef.current};return;}if(reason==='signout')guestDraft.current=null;proofTarget.current=null;setProjects([]);projectsRef.current=[];setOrders([]);if(!guestDraft.current){setCart([]);setDesign(initialDesign());}setAdvice('');setBrief('');setBrand({name:'Avalon Print',tagline:'Make your mark.',primary:'#2449f8',secondary:'#171719',accent:'#c6ee48',font:'Arial'});});
 const requireWorkspace=()=>{if(!account.session||!account.workspace){setAccountOpen(true);toast.info('Sign in and choose a workspace to save your work.');return false;}if(account.loading||account.error){toast.error(account.error||'Your workspace is still loading.');return false;}return true;};
 const go=useCallback((v:View)=>{setView(v);setMobileOpen(false);if(typeof window!=='undefined'){window.history.pushState({},'', '#/'+v);window.scrollTo({top:0,behavior:'smooth'});}},[]);
 useEffect(()=>{const sync=()=>{const v=window.location.hash.slice(2).split('?')[0] as View;if(navs.some(n=>n[0]===v))setView(v);};sync();window.addEventListener('popstate',sync);window.addEventListener('hashchange',sync);const k=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(x=>!x);}};window.addEventListener('keydown',k);fetch('/api/print/status').then(r=>r.ok?r.json():null).then(x=>{if(x && typeof x==="object" && "storage" in x && "ai" in x)setServer({storage:!!x.storage,ai:!!x.ai});}).catch(()=>{});return()=>{window.removeEventListener('popstate',sync);window.removeEventListener('hashchange',sync);window.removeEventListener('keydown',k);};},[]);
 const openProduct=(id:string)=>{setDesign(initialDesign(id));go('studio');};
 const saveProject=async(d=design):Promise<Design|undefined>=>{if(!requireWorkspace()||!account.workspace)return;if(saveLock.current){toast.info('A save is already in progress.');return;}saveLock.current=true;setSaving(true);const epoch=account.epoch.current;try{const previous=projectsRef.current.find(p=>p.id===d.id);const saved=await saveCloudProject(account.workspace.id,d,previous?.version||0);if(epoch!==account.epoch.current)return;setDesign(current=>current.id!==d.id?current:fingerprint(current)===fingerprint(d)?saved:{...current,version:saved.version});const next=[saved,...projectsRef.current.filter(p=>p.id!==saved.id)];projectsRef.current=next;setProjects(next);toast.success('Saved to '+account.workspace.name+' · version '+saved.version);return saved;}catch(e){toast.error((e as Error).message);return;}finally{saveLock.current=false;setSaving(false);}};
 const approveProof=async(d:Design)=>{if(!requireWorkspace()||!account.workspace)return false;const previous=proofTarget.current?.id===d.id&&proofTarget.current.version===d.version?proofTarget.current:projectsRef.current.find(p=>p.id===d.id);const saved=previous&&fingerprint(previous)===fingerprint(d)?previous:await saveProject(d);if(!saved)return false;try{await approveCloudProof(account.workspace.id,saved);toast.success('Proof approval saved for version '+saved.version);return true;}catch(e){toast.error((e as Error).message);return false;}};
 const saveBrand=async()=>{if(!requireWorkspace()||!account.workspace)return;try{await saveCloudBrand(account.workspace.id,brand);toast.success('Brand kit saved');}catch(e){toast.error((e as Error).message);}};
 const duplicateProject=async(d:Design)=>{await saveProject({...structuredClone(d),id:uid(),name:(d.name+' copy').slice(0,80),version:1});};
 const createJobs=async()=>{if(!requireWorkspace()||!account.workspace||busy)return;setBusy(true);const done:string[]=[];const epoch=account.epoch.current;try{for(const item of cart){const previous=projectsRef.current.find(p=>p.id===item.design.id);const saved=previous&&fingerprint(previous)===fingerprint(item.design)?previous:await saveProject(item.design);if(!saved)throw Error('Save the design before submitting the job.');const order=await submitCloudOrder(account.workspace.id,saved,item.key);if(epoch!==account.epoch.current)return;setOrders(all=>[toOrder(order),...all.filter(o=>o.id!==order.id)]);done.push(item.key);}setCartOpen(false);go('production');toast.success('Production requests saved. No payment has been collected.');}catch(e){toast.error((e as Error).message);}finally{if(epoch===account.epoch.current)setCart(all=>all.filter(item=>!done.includes(item.key)));setBusy(false);}};
 const updateJob=async(id:string,status:string)=>{if(!requireWorkspace()||!account.workspace)return false;const old=orders.find(o=>o.id===id);if(!old)return false;try{const result=await transitionOrder(account.workspace.id,id,old.status,status);setOrders(all=>all.map(o=>o.id===id?{...o,status:result.status}:o));toast.success('Production stage saved');return true;}catch(e){toast.error((e as Error).message);return false;}};
 const openRevision=async(o:Order)=>{if(!o.projectId||!o.version||!account.workspace)return;const epoch=account.epoch.current;try{const {data,error}=await cloud().from('pw_revisions').select('design').eq('workspace_id',account.workspace.id).eq('project_id',o.projectId).eq('version',o.version).single();if(error)throw error;if(epoch!==account.epoch.current)return;const d=await hydrateDesign(data.design);if(epoch!==account.epoch.current)return;proofTarget.current=d;setDesign(d);go('studio');}catch(e){toast.error((e as Error).message);}};
 const exportWorkspace=()=>download(JSON.stringify({format:'presswerk-workspace',version:1,projects,orders,brand,activeDesign:design},null,2),'presswerk-workspace.json');
 const importWorkspace=async(file?:File)=>{if(!file)return;if(account.workspace){toast.info('Open an imported design in the studio and save it as a new project. Workspace files cannot replace cloud records.');return;}try{if(file.size>25*1024*1024)throw Error('Maximum workspace file size is 25MB.');const d=JSON.parse(await file.text());if(d.format!=='presswerk-workspace'||d.version!==1||!Array.isArray(d.projects)||!Array.isArray(d.orders))throw Error('Choose a valid Avalon Print workspace file.');const safeDesign=(x:Design)=>{if(!products.some(p=>p.id===x.productId)||typeof x.name!=='string'||x.name.length>80||!Array.isArray(x.layers)||x.layers.length>100||typeof x.background!=='string'||!/^#[0-9a-fA-F]{6}$/.test(x.background)||!Number.isInteger(x.version)||x.version<1||typeof x.updatedAt!=='string'||!Number.isFinite(Date.parse(x.updatedAt)))throw Error('Invalid project data.');calculateQuote({...x,shipping:0});for(const l of x.layers){if(!['text','image','shape'].includes(l.type)||!Number.isFinite(l.x)||!Number.isFinite(l.y)||!Number.isFinite(l.size)||typeof l.text!=='string')throw Error('Invalid design layer.');if(l.size<1||l.size>50||l.x<0||l.x>100||l.y<0||l.y>100||!Number.isFinite(l.opacity)||l.opacity<0||l.opacity>1||!Number.isFinite(l.rotation)||typeof l.color!=='string'||!/^#[0-9a-fA-F]{6}$/.test(l.color))throw Error('Invalid layer settings.');if(l.src&&!/^data:image\/(png|jpeg|webp);base64,/.test(l.src))throw Error('Invalid image data.');}return x;};const nextProjects=d.projects.map(safeDesign).map((p:Design)=>({...p,id:typeof p.id==='string'?p.id:uid()}));const nextOrders=d.orders.map((o:Order)=>{if(!o||typeof o.id!=='string'||typeof o.name!=='string'||o.name.length>100||!products.some(p=>p.id===o.productId)||!Number.isInteger(o.quantity)||o.quantity<1||o.quantity>100000||!Number.isFinite(o.total)||o.total<0||!statuses.includes(o.status)||typeof o.city!=='string'||typeof o.date!=='string'||!Number.isFinite(Date.parse(o.date)))throw Error('Invalid production job. Workspace was not changed.');return o;});const nextActive=d.activeDesign?safeDesign(d.activeDesign):null;if(d.brand&&!['name','tagline','primary','secondary','accent','font'].every(k=>typeof d.brand[k]==='string'))throw Error('Invalid brand kit.');if(d.brand&&!['primary','secondary','accent'].every(k=>/^#[0-9a-fA-F]{6}$/.test(d.brand[k])))throw Error('Invalid brand colours.');setProjects(nextProjects);setOrders(nextOrders);if(nextActive)setDesign({...nextActive,id:typeof nextActive.id==='string'?nextActive.id:uid()});if(d.brand)setBrand(d.brand);toast.success('Workspace imported');}catch(e){toast.error((e as Error).message);}};
 const makeQuote=(d:Design)=>{const q=calculateQuote({...d,shipping:0});if(q.quoteOnly){download(JSON.stringify({type:'Request for quotation',project:d,required:['Confirmed unit price','Materials','Setup and finishing','Shipping','Tax','Production date']},null,2),'presswerk-quote-request.json');toast.success('Specification exported for a supplier quotation');return;}setCart(c=>[...c,{key:uid(),design:structuredClone(d),quote:q}]);setCartOpen(true);};
 const adviser=async()=>{if(brief.trim().length<8){toast.error('Tell us a little more about your project.');return;}setBusy(true);const advisorEpoch=account.epoch.current;if(server.ai){try{const r=await fetch('/api/print/assistant',{method:'POST',headers:await authHeaders(),body:JSON.stringify({brief,productId:design.productId,workspaceId:account.workspace?.id})});const j=await r.json() as {error?:string;text:string};if(!r.ok)throw Error(j.error||'Assistant unavailable');if(advisorEpoch===account.epoch.current)setAdvice(j.text);setBusy(false);return;}catch{if(advisorEpoch!==account.epoch.current){setBusy(false);return;}toast.error('AI service unavailable. Showing catalogue guidance.');}}
 const b=brief.toLowerCase();const picks=products.filter(p=>b.includes(p.name.toLowerCase().split(' ')[0])||b.includes(p.category.toLowerCase().split(' ')[0]));const match=picks.length?picks.slice(0,3):b.includes('event')?[products[0],products[8],products[3]]:b.includes('brand')?[products[0],products[1],products[2]]:[products[0],products[3],products[4]];
 setAdvice('Recommended starting points: '+match.map(p=>p.name).join(', ')+'.\n\nUse one consistent colour palette and keep the headline short. Upload your logo at its final print size, leave a safe margin around text, and approve a physical sample for colour-critical work.\n\n'+match.map(p=>p.name+': '+(p.quoteOnly?'supplier quotation required':money(p.price)+' planning estimate for '+p.quantity)+' · '+p.method).join('\n')+'\n\nCatalogue guidance is active. Connect a model provider for generative design advice.');setBusy(false);};
 return <div className="presswerk"><Toaster position="bottom-right" richColors/><div className="top-strip"><a href="https://avaloncreative.group/" className="avalon-parent-link">By Avalon Creative Group <ArrowUpRight size={12}/></a><span>CANADA · CAD <span className="strip-cross">✳</span></span></div><header className="main-header"><button className="brandmark" onClick={()=>go('discover')} aria-label="Avalon Print home"><span className="brand-symbol">A<span>✳</span></span><span>AVALON PRINT<sup>✳</sup></span></button><nav className="desktop-nav">{navs.slice(0,4).map(([v,label])=><button key={v} className={view===v?'active':''} onClick={()=>go(v)}>{label}{v==='studio'&&<span className="tiny-new">NEW</span>}</button>)}<DropdownMenu><DropdownMenuTrigger className="nav-more">More <ChevronDown size={14}/></DropdownMenuTrigger><DropdownMenuContent align="end">{navs.slice(4).map(([v,label,Icon])=><DropdownMenuItem key={v} onSelect={()=>go(v)}><Icon/>{label}</DropdownMenuItem>)}</DropdownMenuContent></DropdownMenu></nav><div className="header-actions"><button className="icon-button search-key" aria-label="Search products and tools" onClick={()=>setSearchOpen(true)}><Search size={19}/><kbd>⌘ K</kbd></button><button className="icon-button cart-trigger" aria-label={'Open quote basket, '+cart.length+' items'} onClick={()=>setCartOpen(true)}><ShoppingBag size={20}/>{cart.length>0&&<span>{cart.length}</span>}</button><button className="account-trigger" onClick={()=>setAccountOpen(true)} aria-label="Open your account">{account.session?account.session.user.email?.slice(0,2).toUpperCase():'Sign in'}</button><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={()=>setMobileOpen(true)}><Menu/></button></div></header>
 <div className="workspace-bar"><span><span className="mini-mark">A</span> Your creative workspace <span className="muted workspace-label">/ {navs.find(n=>n[0]===view)?.[1]}</span></span><button onClick={exportWorkspace}><Download size={14}/>Export workspace</button><span className="workspace-state">{account.loading?'Loading workspace…':saving?'Saving…':account.workspace?account.workspace.name:'Guest studio'}</span></div>
 {account.error&&account.configured&&<div className="cloud-error-banner"><AlertTriangle size={18}/><span>{account.error}</span><button onClick={()=>account.reload().catch(e=>toast.error(e.message))}>Retry</button></div>}
 {view==='discover'&&<Discover openProduct={openProduct} go={go} setAdvisorOpen={setAdvisorOpen}/>}
 {view==='studio'&&<Studio key={(account.session?.user.id||'guest')+(account.workspace?.id||'')+design.id} approveProof={approveProof} saving={saving} design={design} setDesign={setDesign} saveProject={saveProject} makeQuote={makeQuote} brand={brand} setAdvisorOpen={setAdvisorOpen}/>}
 {view==='projects'&&<Projects connected={!!account.workspace} onAccount={()=>setAccountOpen(true)} duplicateProject={duplicateProject} projects={projects} setProjects={setProjects} orders={orders} openProduct={openProduct} setDesign={setDesign} go={go} exportWorkspace={exportWorkspace} importWorkspace={importWorkspace}/>}
 {view==='production'&&<Production key={(account.session?.user.id||'guest')+(account.workspace?.id||'')} openRevision={openRevision} connected={!!account.workspace} updateJob={updateJob} orders={orders} setOrders={setOrders}/>}
 {view==='pricing'&&<Pricing openProduct={openProduct}/>}
 {view==='brand'&&<BrandCentre saveBrand={saveBrand} connected={!!account.workspace} brand={brand} setBrand={setBrand} design={design} setDesign={setDesign} go={go}/>}
 {view==='network'&&<Network/>}
 {view==='developers'&&<Developers/>}
 {view==='settings'&&<WorkspaceSettings key={(account.session?.user.id||'guest')+(account.workspace?.id||'')+(account.role||'')} workspace={account.workspace} role={account.role} onAccount={()=>setAccountOpen(true)} onJoined={account.reload}/>}
 {view==='roadmap'&&<Roadmap/>}
 {view!=='studio'&&<footer><div className="footer-top"><span>GOOD IDEAS DESERVE<br/>A PHYSICAL FORM.</span><button className="round-arrow" onClick={()=>go('studio')} aria-label="Open design studio"><ArrowUpRight/></button></div><div className="footer-bottom"><span>AVALON PRINT <span className="muted">/ THE PRINT PLATFORM</span></span><a href="https://avaloncreative.group/" className="avalon-footer-link">By Avalon Creative Group <ArrowUpRight size={13}/></a><button onClick={()=>go('developers')}>Built to connect <ArrowUpRight size={14}/></button></div><div className="footer-word">AVALON PRINT<span>✳</span></div></footer>}
 <button className="advisor-fab" onClick={()=>setAdvisorOpen(true)}><Sparkles size={17}/><span>Print advisor</span></button>
 <Account key={account.session?.user.id||'guest'} open={accountOpen} setOpen={setAccountOpen} configured={account.configured} session={account.session} workspace={account.workspace} workspaces={account.workspaces} role={account.role} onWorkspace={account.selectWorkspace} onRefresh={account.reload} onCreated={account.created} onSignOut={account.signOut}/>
 <Dialog open={searchOpen} onOpenChange={setSearchOpen}><DialogContent className="search-dialog"><DialogHeader><DialogTitle>Find your next project</DialogTitle><DialogDescription>Search products, studios and workspaces.</DialogDescription></DialogHeader><Command><CommandInput placeholder="Business cards, packaging, pricing…"/><CommandList><CommandEmpty>No results. Try a product family.</CommandEmpty><CommandGroup heading="Workspaces">{navs.map(([v,label,Icon])=><CommandItem key={v} value={label} onSelect={()=>{go(v);setSearchOpen(false);}}><Icon/>{label}</CommandItem>)}</CommandGroup><CommandGroup heading="Print catalogue">{products.map(p=><CommandItem key={p.id} value={p.name+' '+p.category} onSelect={()=>{openProduct(p.id);setSearchOpen(false);}}><Package/>{p.name}<span className="ml-auto text-muted-foreground">{p.quoteOnly?'Custom quote':money(p.price)}</span></CommandItem>)}</CommandGroup></CommandList></Command></DialogContent></Dialog>
 <Sheet open={mobileOpen} onOpenChange={setMobileOpen}><SheetContent><SheetHeader><SheetTitle>Avalon Print</SheetTitle><SheetDescription>Your print workspace</SheetDescription></SheetHeader><nav className="mobile-nav">{navs.map(([v,label,Icon])=><button key={v} onClick={()=>go(v)}><Icon size={20}/>{label}</button>)}</nav></SheetContent></Sheet>
 <Sheet open={advisorOpen} onOpenChange={setAdvisorOpen}><SheetContent className="advisor-sheet"><SheetHeader><SheetTitle><Sparkles className="inline mr-2"/>Print advisor</SheetTitle><SheetDescription>Find the right format, material and production approach.</SheetDescription></SheetHeader><div className="sheet-body"><Chip color="blue">{server.ai?'AI assistant':'Catalogue guidance'}</Chip><h3>What are you making?</h3><textarea value={brief} onChange={e=>setBrief(e.target.value)} placeholder="I’m launching a coffee brand and need packaging, cards and merchandise for 100 customers…" rows={7}/><div className="prompt-chips">{['A new brand launch','An exhibition in Calgary','A restaurant opening'].map(s=><button key={s} onClick={()=>setBrief(s)}>{s}</button>)}</div><button className="btn primary full" disabled={busy} onClick={adviser}><Sparkles size={16}/>{busy?'Considering your project…':'Explore my options'}</button>{advice&&<div className="advice-result">{advice}</div>}<p className="fineprint">Recommendations are starting points. Final specifications and production availability need approval.</p></div></SheetContent></Sheet>
 <Sheet open={cartOpen} onOpenChange={setCartOpen}><SheetContent className="quote-sheet"><SheetHeader><SheetTitle>Your quote basket <span className="muted">({cart.length})</span></SheetTitle><SheetDescription>Planning estimates in CAD. No payment or production commitment.</SheetDescription></SheetHeader><div className="sheet-body">{cart.length===0?<div className="empty-state"><ShoppingBag/><h3>A good idea starts here.</h3><p>Configure a product in the studio and add it to your quote.</p><button className="btn primary" onClick={()=>{setCartOpen(false);go('studio');}}>Open studio <ArrowRight size={16}/></button></div>:<>{cart.map((item,i)=><div className="cart-item" key={i}><div className="cart-swatch" style={{background:item.design.background}}><span style={{color:item.design.layers[0]?.color}}>{item.design.layers[0]?.text.split('\n')[0]}</span></div><div><h4>{item.design.name}</h4><p>{item.quote.product.name} · {item.design.quantity}</p><small>{item.design.tier} / {item.design.finish}</small></div><div><strong>{money(item.quote.total)}</strong><button className="text-button" onClick={()=>setCart(c=>c.filter((_,n)=>n!==i))}>Remove</button></div></div>)}<div className="quote-total"><span>Product estimate</span><strong>{money(cart.reduce((a,c)=>a+c.quote.total,0))}</strong></div><p className="fineprint">Delivery, tax, artwork repair and non-standard finishing are confirmed separately. Prices are proposed launch estimates.</p><button className="btn primary full" onClick={()=>{download(JSON.stringify({company:'Avalon Print',type:'Non-binding estimate',createdAt:new Date().toISOString(),currency:'CAD',items:cart,tax:'Excluded',delivery:'To be confirmed'},null,2),'presswerk-quote.json');toast.success('Quote downloaded');}}><Download size={16}/>Download itemized quote</button><button className="btn secondary full" disabled={busy} onClick={createJobs}><ClipboardList size={16}/>Save production requests</button></>}</div></SheetContent></Sheet>
 </div>;
}

function Discover({openProduct,go,setAdvisorOpen}:{openProduct:(id:string)=>void;go:(v:View)=>void;setAdvisorOpen:(b:boolean)=>void}){
 const [cat,setCat]=useState('Everything');const [search,setSearch]=useState('');const [sort,setSort]=useState('Featured');const [onlyInstant,setOnlyInstant]=useState(false);const [expanded,setExpanded]=useState(false);
 const list=useMemo(()=>{let l=products.filter(p=>(cat==='Everything'||p.category===cat)&&(!onlyInstant||!p.quoteOnly)&&(!search||(p.name+' '+p.description+' '+p.method).toLowerCase().includes(search.toLowerCase())));if(sort==='Price: low to high')l=l.sort((a,b)=>(a.price||Infinity)-(b.price||Infinity));if(sort==='A–Z')l=l.sort((a,b)=>a.name.localeCompare(b.name));return l;},[cat,search,sort,onlyInstant]);
 return <main className="discover-page"><section className="creative-hero"><div className="hero-copy"><div className="eyebrow"><span className="asterisk">✳</span> THE POSSIBILITIES ARE PHYSICAL.</div><h1>Your ideas.<br/><span>Made tangible.</span></h1><p>From the first business card to the whole brand universe.<br className="desktop-only"/> Design it. See it. Make it happen.</p><div className="hero-actions"><button className="btn primary" onClick={()=>go('studio')}>Create something <ArrowUpRight size={18}/></button><button className="btn text" onClick={()=>setAdvisorOpen(true)}><Sparkles size={17}/>Help me choose</button></div><div className="hero-meta"><span><Check size={14}/>Live design preview</span><span><Check size={14}/>Transparent estimates</span></div></div><div className="hero-image"><img src={imageSrc('collection')} alt="Cobalt business cards, custom packaging, apparel and a mug arranged in a sunlit print studio" fetchPriority="high"/><div className="image-caption"><span>PRESSWERK / SAMPLE BRAND</span><span>EXAMPLE COLLECTION <ArrowUpRight size={14}/></span></div><div className="image-stamp">DESIGNED<br/>BY YOU.<span>✳</span></div></div></section>
 <section className="catalogue" id="catalogue"><div className="section-title"><div><span className="eyebrow">YOUR NEXT PROJECT STARTS HERE</span><h2>What are we making?</h2></div><span className="catalog-count">{products.length} formats. Endless possibilities.</span></div><div className="catalog-controls"><div className="search-field"><Search size={19}/><input aria-label="Search catalogue" placeholder="Find your perfect format…" value={search} onChange={e=>{setSearch(e.target.value);setExpanded(true);}}/>{search&&<button onClick={()=>setSearch('')} aria-label="Clear search"><X size={16}/></button>}</div><Pick value={sort} onChange={setSort} options={['Featured','Price: low to high','A–Z']} label="Sort products"/><label className="switch-label"><Switch checked={onlyInstant} onCheckedChange={setOnlyInstant}/>Instant estimates</label></div><Tabs value={cat} onValueChange={v=>{setCat(v);setExpanded(v!=='Everything');}}><TabsList className="category-tabs" variant="line">{categories.map(c=><TabsTrigger value={c} key={c}>{c}</TabsTrigger>)}</TabsList></Tabs><div className="catalogue-grid">{list.slice(0,expanded?100:6).map((p,i)=><button className="product-card" key={p.id} onClick={()=>openProduct(p.id)}><div className="product-visual"><ProductImage p={p}/>{p.tag&&<span className={'product-tag '+(i===1?'lime':'')}>{p.tag}</span>}<span className="product-open"><ArrowUpRight size={21}/></span></div><div className="product-info"><span className="eyebrow">{p.category}</span><div><h3>{p.name}</h3><span className="price">{p.quoteOnly?'Let’s quote it':money(p.price)}</span></div><p>{p.description}</p><small>{p.quoteOnly?'Specification-led pricing':`Planning estimate · ${p.quantity} ${p.unit}`}</small></div></button>)}</div>{!list.length&&<div className="empty-state"><Search/><h3>No formats match yet.</h3><button className="btn secondary" onClick={()=>{setSearch('');setCat('Everything');setOnlyInstant(false);}}>Reset filters</button></div>}{!expanded&&list.length>6&&<div className="center"><button className="btn secondary" onClick={()=>setExpanded(true)}>Explore all {products.length} formats <Plus size={17}/></button></div>}</section>
 <section className="studio-invitation"><div><span className="eyebrow">THE DESIGN STUDIO</span><h2>Less guesswork.<br/>More <em>“that’s the one.”</em></h2><p>Upload your artwork. Find your colours. Move every detail into place. See your idea before it leaves the screen.</p><button className="btn white" onClick={()=>go('studio')}>Step inside the studio <ArrowUpRight size={18}/></button></div><div className="studio-steps">{[['01','Make it yours','Layer artwork, type and colour on a measured canvas.'],['02','See the details','Inspect safe areas, resolution and your live proof.'],['03','Find your fit','Compare materials, quantities and service tiers.']].map(([n,t,d])=><div key={n}><span>{n}</span><section><h3>{t}</h3><p>{d}</p></section><ArrowUpRight size={20}/></div>)}</div></section>
 <section className="workflows"><div className="section-title"><div><span className="eyebrow">ONE CONNECTED WORKSPACE</span><h2>Every part of the process.</h2></div></div><div className="workflow-grid">{([['brand','Your brand, everywhere.','Keep colours and typography consistent across the entire collection.',Palette],['production','A clear path to production.','Move draft jobs through artwork, printing, finishing and dispatch.',Printer],['developers','Print, connected.','Explore a structured catalogue, quote API and integration specification.',Code2]] as [View,string,string,React.ElementType][]).map(([v,t,d,Icon])=><button key={v} onClick={()=>go(v)}><Icon size={28}/><h3>{t}</h3><p>{d}</p><span>Explore <ArrowUpRight size={17}/></span></button>)}</div></section></main>;
}

const Mockup=React.lazy(()=>import('./mockup'));
function Studio({design,setDesign,saveProject,makeQuote,brand,setAdvisorOpen,approveProof,saving}:{design:Design;setDesign:React.Dispatch<React.SetStateAction<Design>>;saveProject:(d?:Design)=>Promise<Design|undefined>;approveProof:(d:Design)=>Promise<boolean>;saving:boolean;makeQuote:(d:Design)=>void;brand:Brand;setAdvisorOpen:(b:boolean)=>void}){
 const [selected,setSelected]=useState('headline');const [tool,setTool]=useState('templates');const [mode,setMode]=useState('artwork');const [zoom,setZoom]=useState(90);const [guides,setGuides]=useState(true);const [spin,setSpin]=useState(false);const [proofOpen,setProofOpen]=useState(false);const [approved,setApproved]=useState(false);const [undo,setUndo]=useState<Design[]>([]);const [redo,setRedo]=useState<Design[]>([]);const [palette,setPalette]=useState<string[]>([]);const svg=useRef<SVGSVGElement>(null);const file=useRef<HTMLInputElement>(null);const dragging=useRef<{id:string;dx:number;dy:number}|null>(null);
 const product=products.find(p=>p.id===design.productId)!;const ratio=product.height/product.width;const H=100*ratio;const layer=design.layers.find(l=>l.id===selected);const quote=calculateQuote({...design,shipping:0});
 const commit=(fn:(d:Design)=>Design)=>{setUndo(s=>[...s.slice(-29),structuredClone(design)]);setRedo([]);setApproved(false);setDesign(d=>({...fn(d),updatedAt:new Date().toISOString()}));};
 const patch=(x:Partial<Design>)=>commit(d=>({...d,...x}));const patchLayer=(x:Partial<DesignLayer>)=>commit(d=>({...d,layers:d.layers.map(l=>l.id===selected?{...l,...x}:l)}));
 const undoAction=()=>{if(!undo.length)return;setRedo(r=>[...r,design]);setDesign(undo[undo.length-1]);setUndo(h=>h.slice(0,-1));};const redoAction=()=>{if(!redo.length)return;setUndo(h=>[...h,design]);setDesign(redo[redo.length-1]);setRedo(r=>r.slice(0,-1));};
 const applyTemplate=(t:typeof templates[0])=>{const fg=['#f2f0ea','#c6ee48','#e5e8ed','#f57439'].includes(t.color)?'#171719':'#ffffff';const d=initialDesign(design.productId);commit(old=>({...old,background:t.color,layers:d.layers.map((l,i)=>({...l,text:i===0?t.text:brand.name+'  /  CREATED BY YOU',color:fg,font:brand.font}))}));};
 const addLayer=(type:'text'|'shape')=>{const id=uid();commit(d=>({...d,layers:[...d.layers,{id,type,text:type==='text'?'Your words here':'',x:10,y:15,size:7,color:design.background==='#171719'?'#ffffff':'#171719',rotation:0,opacity:1,width:30,height:25,font:brand.font}]}));setSelected(id);setTool('layers');};
 const upload=async(f?:File)=>{if(!f)return;try{if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Upload PNG, JPG or WebP artwork.');if(f.size>12*1024*1024)throw Error('Choose an image under 12MB.');const src=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(f);});const im=new Image();im.src=src;await im.decode();if(im.width*im.height>60000000)throw Error('Image is too large. Use an image below 60 megapixels.');const id=uid();const width=60;const height=Math.min(80,width*(im.height/im.width)/ratio);commit(d=>({...d,imageWidth:im.width,imageHeight:im.height,layers:[...d.layers,{id,type:'image',text:f.name,src,x:20,y:15,size:10,color:'#ffffff',rotation:0,opacity:1,width,height,naturalWidth:im.width,naturalHeight:im.height}]}));setSelected(id);setTool('layers');const c=document.createElement('canvas');c.width=40;c.height=40;const cx=c.getContext('2d')!;cx.drawImage(im,0,0,40,40);const pixels=cx.getImageData(0,0,40,40).data;const counts:Record<string,number>={};for(let i=0;i<pixels.length;i+=16){const rgb=[pixels[i],pixels[i+1],pixels[i+2]].map(v=>Math.min(255,Math.round(v/32)*32).toString(16).padStart(2,'0'));const color='#'+rgb.join('');counts[color]=(counts[color]||0)+1;}setPalette(Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,6).map(x=>x[0]));toast.success('Artwork added. Colours extracted from your image.');}catch(e){toast.error((e as Error).message);}if(file.current)file.current.value='';};
 const textIssues=design.layers.filter(l=>l.type==='text'&&l.size/100*product.width/25.4*72<6).length;const edgeIssues=design.layers.filter(l=>l.x<3||l.y<3||l.x>94||l.y>94).length;const imageLayers=design.layers.filter(l=>l.type==='image');const ppis=imageLayers.filter(l=>l.naturalWidth).map(l=>Math.round(l.naturalWidth!/((l.width||60)/100*product.width/25.4)));const ppi=ppis.length?Math.min(...ppis):null;const unresolved=imageLayers.length-ppis.length;const issues=textIssues+edgeIssues+ppis.filter(p=>p<150).length+unresolved;
 const exportSVG=()=>{if(!svg.current)return;const clone=svg.current.cloneNode(true) as SVGSVGElement;clone.querySelectorAll('.selection-only').forEach(e=>e.remove());clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width',product.width+'mm');clone.setAttribute('height',product.height+'mm');download(new XMLSerializer().serializeToString(clone),design.name.replace(/[^a-z0-9]/gi,'-')+'.svg','image/svg+xml');toast.success('Artwork SVG exported. Confirm bleed and colour profile with your printer.');};
 const exportPNG=async()=>{const {designCanvas}=await import('./mockup');const c=await designCanvas(design,Math.min(4096,Math.round(Math.max(product.width,product.height)/25.4*300)));const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=design.name.replace(/[^a-z0-9]/gi,'-')+'.png';a.click();toast.success(`PNG exported at ${c.width} × ${c.height}px`);};
 const pointerDown=(e:React.PointerEvent,id:string)=>{if(mode!=='artwork'||!svg.current)return;e.stopPropagation();const l=design.layers.find(x=>x.id===id)!;const box=svg.current.getBoundingClientRect();setSelected(id);setUndo(h=>[...h.slice(-29),structuredClone(design)]);setRedo([]);setApproved(false);dragging.current={id,dx:(e.clientX-box.left)/box.width*100-l.x,dy:(e.clientY-box.top)/box.height*100-l.y};svg.current.setPointerCapture(e.pointerId);};
 const artwork=<svg ref={svg} viewBox={`0 0 100 ${H}`} className="artboard-svg" aria-label="Editable artwork canvas" onPointerMove={e=>{if(!dragging.current||!svg.current)return;const b=svg.current.getBoundingClientRect();const {id,dx,dy}=dragging.current;const x=Math.min(98,Math.max(0,(e.clientX-b.left)/b.width*100-dx));const y=Math.min(98,Math.max(0,(e.clientY-b.top)/b.height*100-dy));setDesign(d=>({...d,layers:d.layers.map(l=>l.id===id?{...l,x,y}:l)}));}} onPointerUp={()=>dragging.current=null} onPointerCancel={()=>dragging.current=null} onClick={()=>setSelected('')}><rect width="100" height={H} fill={design.background}/>{design.layers.map(l=><g key={l.id} transform={`translate(${l.x} ${l.y*H/100}) rotate(${l.rotation})`} opacity={l.opacity} style={{cursor:'move'}} onPointerDown={e=>pointerDown(e,l.id)} onClick={e=>{e.stopPropagation();setSelected(l.id);}}>{l.type==='text'?<text fill={l.color} fontSize={l.size} fontFamily={l.font||'Arial'} fontWeight={l.weight||700} dominantBaseline="hanging">{l.text.split('\n').map((line,i)=><tspan key={i} x="0" dy={i===0?0:l.size*1.1}>{line}</tspan>)}</text>:l.type==='shape'?<rect width={l.width||30} height={(l.height||25)*H/100} fill={l.color}/>:<image href={l.src} width={l.width||60} height={(l.height||40)*H/100} preserveAspectRatio="none"/>}{selected===l.id&&mode==='artwork'&&<rect className="selection-only" x={-1} y={-1} width={l.type==='text'?Math.min(95,l.size*Math.max(...l.text.split('\n').map(s=>s.length))*.58):(l.width||30)+2} height={l.type==='text'?l.size*l.text.split('\n').length*1.12:(l.height||25)*H/100+2} fill="none" stroke="#7dadff" strokeWidth=".35" strokeDasharray="1.1 .8"/>}</g>)}{guides&&<rect className="selection-only" x="3" y={3*H/100} width="94" height={H*.94} rx=".1" fill="none" stroke="#fa93ac" strokeDasharray="1 .8" strokeWidth=".25" pointerEvents="none"/>}</svg>;
 return <main className="studio-page"><div className="studio-header"><div><span className="studio-icon"><Layers size={21}/></span><div><input className="project-name" aria-label="Project name" value={design.name} maxLength={80} onChange={e=>setDesign(d=>({...d,name:e.target.value}))}/><p>{product.name} <span>·</span> {product.width} × {product.height} mm <span>·</span> Editable artwork</p></div></div><div className="studio-header-actions"><button className="btn secondary" disabled={saving} onClick={()=>saveProject(design)}><Save size={16}/><span>Save project</span></button><button className="btn primary" onClick={()=>setProofOpen(true)}>Review proof <ArrowRight size={17}/></button></div></div>
 <div className="studio-layout"><aside className="studio-left"><Tabs value={tool} onValueChange={setTool}><TabsList className="tool-tabs"><TabsTrigger value="templates"><LayoutTemplate size={18}/><span>Templates</span></TabsTrigger><TabsTrigger value="layers"><Layers size={18}/><span>Layers</span></TabsTrigger><TabsTrigger value="brand"><Palette size={18}/><span>Colour</span></TabsTrigger></TabsList><TabsContent value="templates"><div className="panel-heading"><h3>A starting point.</h3><p>Make it your own from here.</p></div><div className="template-grid">{templates.map(t=><button className="template-card" key={t.id} onClick={()=>applyTemplate(t)}><div style={{background:t.color,color:['#f2f0ea','#c6ee48','#e5e8ed','#f57439'].includes(t.color)?'#171719':'#ffffff'}}>{t.text.split('\n').map((s,i)=><React.Fragment key={i}>{s}<br/></React.Fragment>)}</div><strong>{t.name}</strong><span>{t.type}</span></button>)}</div><div className="assistant-mini"><Sparkles size={20}/><h4>Find your direction.</h4><p>Get help choosing a format and preparing your artwork.</p><button onClick={()=>setAdvisorOpen(true)}>Ask the print advisor <ArrowUpRight size={15}/></button></div></TabsContent><TabsContent value="layers"><div className="panel-heading"><h3>Build your design.</h3><p>Select a layer to edit its details.</p></div><div className="add-tools"><button onClick={()=>addLayer('text')}><Type/>Text</button><button onClick={()=>file.current?.click()}><ImageIcon/>Image</button><button onClick={()=>addLayer('shape')}><Square/>Shape</button></div><div className="layer-list">{[...design.layers].reverse().map(l=><button key={l.id} onClick={()=>setSelected(l.id)} className={l.id===selected?'selected':''}>{l.type==='text'?<Type size={16}/>:l.type==='image'?<ImageIcon size={16}/>:<Square size={16}/>}<span>{l.text||'Colour block'}</span><Eye size={14}/></button>)}</div>{layer&&<div className="layer-properties">{layer.type==='text'&&<><label>Text<textarea value={layer.text} rows={4} onChange={e=>patchLayer({text:e.target.value})}/></label><label>Typeface<Pick label="Typeface" value={layer.font||'Arial'} onChange={font=>patchLayer({font})} options={['Arial','Georgia','Verdana','Courier New']}/></label><label>Type size <span>{layer.size}%</span><Slider aria-label="Type size" min={1} max={35} step={.5} value={[layer.size]} onValueChange={v=>patchLayer({size:v[0]})}/></label></>}{layer.type!=='image'&&<label className="colour-field">Colour<input type="color" value={layer.color} onChange={e=>patchLayer({color:e.target.value})}/><span>{layer.color.toUpperCase()}</span></label>}<label>Rotation <span>{Math.round(layer.rotation)}°</span><Slider aria-label="Layer rotation" min={-180} max={180} value={[layer.rotation]} onValueChange={v=>patchLayer({rotation:v[0]})}/></label><label>Opacity <span>{Math.round(layer.opacity*100)}%</span><Slider aria-label="Layer opacity" min={0} max={100} value={[layer.opacity*100]} onValueChange={v=>patchLayer({opacity:v[0]/100})}/></label>{layer.type!=='text'&&<><label>Width <span>{layer.width||30}%</span><Slider aria-label="Layer width" min={5} max={100} value={[layer.width||30]} onValueChange={v=>patchLayer({width:v[0]})}/></label><label>Height <span>{layer.height||25}%</span><Slider aria-label="Layer height" min={5} max={100} value={[layer.height||25]} onValueChange={v=>patchLayer({height:v[0]})}/></label></>}<div className="row"><button className="btn secondary" onClick={()=>{const id=uid();commit(d=>({...d,layers:[...d.layers,{...layer,id,x:Math.min(90,layer.x+5),y:Math.min(90,layer.y+5)}]}));setSelected(id);}}><Copy size={15}/>Duplicate</button><button className="btn danger" aria-label="Delete layer" onClick={()=>{commit(d=>({...d,layers:d.layers.filter(l=>l.id!==selected)}));setSelected('');}}><Trash2 size={16}/></button></div><button className="btn secondary full" onClick={()=>patchLayer({x:10,y:30,rotation:0})}><Move size={15}/>Reset placement</button></div>}</TabsContent><TabsContent value="brand"><div className="panel-heading"><h3>A colour story.</h3><p>Apply your brand or find a new palette.</p></div><label className="colour-field">Canvas<input type="color" value={design.background} onChange={e=>patch({background:e.target.value})}/><span>{design.background.toUpperCase()}</span></label><h4 className="panel-subhead">Your brand palette</h4><div className="colour-palette">{[brand.primary,brand.secondary,brand.accent,'#ffffff','#e8e8e6','#f57439'].map(c=><button key={c} style={{background:c}} aria-label={'Set background '+c} onClick={()=>patch({background:c})}/>)}</div><button className="btn secondary full" onClick={()=>commit(d=>({...d,background:brand.primary,layers:d.layers.map(l=>l.type==='text'?{...l,font:brand.font,color:'#ffffff'}:l)}))}>Apply brand style <Check size={15}/></button>{palette.length>0&&<><h4 className="panel-subhead">Extracted from your artwork</h4><div className="colour-palette">{palette.map(c=><button key={c} style={{background:c}} aria-label={'Use extracted '+c} onClick={()=>patch({background:c})}/>)}</div></>}<p className="fineprint">Screen colours are an RGB approximation. Request a physical proof for exact colour matching.</p></TabsContent></Tabs><input ref={file} className="hidden" type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e.target.files?.[0])}/></aside>
 <section className="studio-stage"><div className="stage-toolbar"><Tabs value={mode} onValueChange={setMode}><TabsList><TabsTrigger value="artwork"><MousePointer2 size={14}/>Artwork</TabsTrigger><TabsTrigger value="mockup"><Box size={14}/>3D mockup</TabsTrigger></TabsList></Tabs><div><button className="icon-button" aria-label="Undo" disabled={!undo.length} onClick={undoAction}><RotateCcw size={17}/></button><button className="icon-button" aria-label="Redo" disabled={!redo.length} onClick={redoAction}><RotateCw size={17}/></button><button className="icon-button" aria-label="Upload artwork" onClick={()=>file.current?.click()}><Upload size={17}/></button><DropdownMenu><DropdownMenuTrigger className="icon-button" aria-label="Export artwork"><Download size={17}/></DropdownMenuTrigger><DropdownMenuContent><DropdownMenuItem onSelect={exportSVG}>Artwork as SVG</DropdownMenuItem><DropdownMenuItem onSelect={exportPNG}>Artwork as PNG</DropdownMenuItem><DropdownMenuItem onSelect={()=>download(JSON.stringify(design,null,2),'presswerk-design.json')}>Editable design JSON</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></div><div className="stage-canvas" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();upload(e.dataTransfer.files[0]);}}>{mode==='artwork'?<><div className="ruler horizontal-ruler"><span>0</span><span>{Math.round(product.width*.25)}</span><span>{Math.round(product.width*.5)}</span><span>{Math.round(product.width*.75)}</span><span>{product.width} mm</span></div><div className="artboard-wrap" style={{width:ratio>1?`${Math.min(70,60/ratio)*zoom/90}%`:`${zoom*.82}%`,maxHeight:'90%',aspectRatio:`${product.width} / ${product.height}`}}>{artwork}</div><div className="canvas-hint">Drag layers to position · Drop an image to upload</div></>:<React.Suspense fallback={<div className="empty-state">Preparing your 3D preview…</div>}><Mockup design={design} spin={spin}/></React.Suspense>}</div><div className="stage-bottom">{mode==='artwork'?<label className="switch-label"><Switch checked={guides} onCheckedChange={setGuides}/>Safe area</label>:<label className="switch-label"><Switch checked={spin} onCheckedChange={setSpin}/>Auto rotate</label>}<span>{product.width} × {product.height} mm</span><div><button aria-label="Zoom out" className="icon-button" onClick={()=>setZoom(z=>Math.max(30,z-10))}><Minus size={15}/></button><span>{zoom}%</span><button aria-label="Zoom in" className="icon-button" onClick={()=>setZoom(z=>Math.min(120,z+10))}><Plus size={15}/></button></div></div></section>
 <aside className="studio-right"><div className="panel-heading"><span className="eyebrow">MAKE IT REAL</span><h3>Your print, your way.</h3></div><label>Product<Select value={design.productId} onValueChange={id=>{const p=products.find(x=>x.id===id)!;patch({productId:id,quantity:p.quantity,finish:'Standard'});}}><SelectTrigger className="pw-select"><SelectValue/></SelectTrigger><SelectContent>{products.map(p=><SelectItem value={p.id} key={p.id}>{p.name}</SelectItem>)}</SelectContent></Select></label><div className="material-summary"><Layers size={18}/><div><strong>{product.material}</strong><span>{product.method}</span></div></div><label>Quantity<input type="number" min="1" max="100000" value={design.quantity} onChange={e=>{const n=Number(e.target.value);if(Number.isInteger(n)&&n>0&&n<=100000)patch({quantity:n});}}/></label><div className="quantity-presets">{(product.quantity===1?[1,12,24,100]:[100,250,500,1000]).map(n=><button key={n} className={design.quantity===n?'selected':''} onClick={()=>patch({quantity:n})}>{n}</button>)}</div><label>Finish<Pick value={design.finish} onChange={finish=>patch({finish})} options={finishesFor(product)} label="Print finish"/></label><label>Service tier<Pick value={design.tier} onChange={tier=>patch({tier:tier as Tier})} options={['Value','Design Plus','Priority']} label="Service tier"/></label><label>Destination<Pick value={design.city} onChange={city=>patch({city})} options={['Calgary','St. John’s','Other Canadian city']} label="Destination city"/></label><div className="preflight-summary"><span className={issues?'warning-icon':'success-icon'}>{issues?<AlertTriangle size={18}/>:<FileCheck2 size={18}/>}</span><div><strong>{issues?`${issues} artwork ${issues===1?'check':'checks'} to review`:'Basic artwork checks clear'}</strong><p>{ppi?`Lowest image resolution: ${ppi} PPI`:unresolved?'Image resolution unverified':'Vector text and shapes'} · Review proof before ordering</p></div></div><div className="studio-quote"><span>{quote.quoteOnly?'CUSTOM PROJECT':'PLANNING ESTIMATE'}</span><div><strong>{quote.quoteOnly?'Let’s quote it.':money(quote.subtotal)}</strong>{!quote.quoteOnly&&<span>{money(quote.unit)} / item</span>}</div><p>{design.tier} · {quote.days} business days estimated production</p><button className="btn primary full" onClick={()=>makeQuote(design)}>{quote.quoteOnly?'Export quote specification':'Add to quote'}<ArrowUpRight size={18}/></button><small>CAD · Tax and delivery separate. Materials, finishes and availability need confirmation.</small></div></aside></div>
 <Dialog open={proofOpen} onOpenChange={setProofOpen}><DialogContent className="proof-dialog"><DialogHeader><DialogTitle>One final look.</DialogTitle><DialogDescription>Review artwork placement and specifications. A screen preview does not guarantee colour or material appearance.</DialogDescription></DialogHeader><div className="proof-layout"><div className="proof-art" style={{aspectRatio:`${product.width}/${product.height}`}}>{React.cloneElement(artwork,{ref:undefined})}</div><div><h3>{design.name}</h3><p>{product.name} · {design.quantity} items</p><ul className="proof-checks"><li><CheckCircle2/>Dimensions: {product.width} × {product.height} mm</li><li>{textIssues?<AlertTriangle/>:<CheckCircle2/>}{textIssues?`${textIssues} text layers below 6pt`:'Text size check clear'}</li><li>{edgeIssues?<AlertTriangle/>:<CheckCircle2/>}{edgeIssues?'Review elements near trim':'Layer origins within safe area'}</li><li>{ppi&&ppi<150?<AlertTriangle/>:<Info/>}{ppi?`Lowest image resolution: ${ppi} PPI`:unresolved?'Image resolution unverified':'No uploaded image resolution to assess'}</li><li><Info/>Bleed, fonts and colour need printer preflight</li></ul><label className="switch-label"><Switch checked={approved} onCheckedChange={setApproved}/>I reviewed the artwork and spelling</label><button className="btn primary full" disabled={!approved} onClick={async()=>{if(await approveProof(design))setProofOpen(false);}}>Save proof approval <Check size={16}/></button><button className="btn secondary full" onClick={exportPNG}><Download size={16}/>Download proof image</button></div></div></DialogContent></Dialog>
 </main>;
}

function PageIntro({eyebrow,title,description,children}:{eyebrow:string;title:string;description:string;children?:React.ReactNode}){return <div className="page-intro"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{children}</div>;}
function Projects({projects,setProjects,orders,openProduct,setDesign,go,exportWorkspace,importWorkspace,connected,onAccount,duplicateProject}:{projects:Design[];setProjects:React.Dispatch<React.SetStateAction<Design[]>>;orders:Order[];openProduct:(id:string)=>void;setDesign:React.Dispatch<React.SetStateAction<Design>>;go:(v:View)=>void;exportWorkspace:()=>void;importWorkspace:(file?:File)=>void;connected:boolean;onAccount:()=>void;duplicateProject:(d:Design)=>Promise<void>}){const [search,setSearch]=useState('');const input=useRef<HTMLInputElement>(null);const list=projects.filter(p=>p.name.toLowerCase().includes(search.toLowerCase()));return <main className="workspace-page"><PageIntro eyebrow="YOUR CREATIVE SPACE" title="Good ideas live here." description="Keep your projects together, return to a design and take the next step."><button className="btn primary" onClick={()=>openProduct('cards')}><Plus size={17}/>New project</button></PageIntro><div className="workspace-notice"><Info size={18}/><span>{connected?'Your projects and artwork are saved privately to your workspace. Every saved change creates a new version.':'Sign in to save projects and return to them from another device.'}</span><button onClick={connected?exportWorkspace:onAccount}>{connected?'Export':'Sign in'} <ArrowUpRight size={16}/></button></div><div className="stat-grid"><div><FolderOpen/><span>Saved projects</span><strong>{projects.length.toString().padStart(2,'0')}</strong></div><div><ClipboardList/><span>Draft production jobs</span><strong>{orders.length.toString().padStart(2,'0')}</strong></div><div><Package/><span>Formats to explore</span><strong>{products.length}</strong></div><div><Palette/><span>One consistent identity</span><button onClick={()=>go('brand')}>Open brand centre <ArrowUpRight size={18}/></button></div></div><div className="section-title"><h2>Your projects</h2><div className="row"><button className="btn secondary" onClick={()=>input.current?.click()}><Upload size={16}/>Import workspace</button><input ref={input} type="file" accept="application/json,.json" className="hidden" onChange={e=>importWorkspace(e.target.files?.[0])}/></div></div><div className="search-field short"><Search size={18}/><input placeholder="Search your projects" aria-label="Search projects" value={search} onChange={e=>setSearch(e.target.value)}/></div>{list.length?<div className="project-grid">{list.map((d,i)=><article className="saved-project" key={d.id}><button className="saved-project-art" style={{background:d.background,color:d.layers[0]?.color}} onClick={()=>{setDesign(d);go('studio');}}>{d.layers[0]?.text.split('\n').map((line,n)=><React.Fragment key={n}>{line}<br/></React.Fragment>)}</button><div><Chip>Version {d.version}</Chip><h3>{d.name}</h3><p>{products.find(p=>p.id===d.productId)?.name} · {d.quantity} items</p><span>{formatDate(d.updatedAt)}</span><DropdownMenu><DropdownMenuTrigger className="icon-button" aria-label={'Actions for '+d.name}><MoreHorizontal/></DropdownMenuTrigger><DropdownMenuContent><DropdownMenuItem onSelect={()=>{setDesign(d);go('studio');}}>Continue editing</DropdownMenuItem><DropdownMenuItem onSelect={()=>duplicateProject(d)}>Duplicate</DropdownMenuItem><DropdownMenuItem onSelect={()=>download(JSON.stringify(d,null,2),d.name+'.json')}>Export design</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></article>)}</div>:<div className="workspace-empty"><div><span className="eyebrow">START WITH SOMETHING GREAT</span><h2>{search?'No matching projects.':'Your next idea belongs here.'}</h2><p>{search?'Try another project name.':'Choose a format, make it yours in the studio, then save it to this workspace.'}</p><button className="btn primary" onClick={()=>openProduct('cards')}>Create your first project <ArrowUpRight size={18}/></button></div><img src={imageSrc('cards')} alt="Cobalt blue printed business cards"/></div>}</main>;}

function Production({orders,setOrders,connected,updateJob,openRevision}:{orders:Order[];setOrders:React.Dispatch<React.SetStateAction<Order[]>>;connected:boolean;updateJob:(id:string,status:string)=>Promise<boolean>;openRevision:(o:Order)=>Promise<void>}){const [examples,setExamples]=useState(false);const [sample,setSample]=useState(exampleOrders);const [city,setCity]=useState('All locations');const [selected,setSelected]=useState<Order|null>(null);const [search,setSearch]=useState('');const [layout,setLayout]=useState('board');const [historyResult,setHistoryResult]=useState<{orderId:string;status:string;events:{id:string;to_status:string;created_at:string}[]}|null>(null);const history=historyResult&&historyResult.orderId===selected?.id&&historyResult.status===selected?.status?historyResult.events:[];useEffect(()=>{let live=true;if(selected&&!selected.example)orderHistory(selected.id).then(events=>{if(live)setHistoryResult({orderId:selected.id,status:selected.status,events});}).catch(e=>{if(live)toast.error(e.message);});return()=>{live=false;};},[selected]);const data=[...orders,...(examples?sample:[])].filter(o=>(city==='All locations'||o.city===city)&&(!search||(o.name+o.id).toLowerCase().includes(search.toLowerCase())));const update=async(id:string,status:string)=>{if(sample.some(o=>o.id===id)){setSample(all=>all.map(o=>o.id===id?{...o,status}:o));setSelected(o=>o?.id===id?{...o,status}:o);return;}if(await updateJob(id,status))setSelected(o=>o?.id===id?{...o,status}:o)};const exportJobs=()=>download(['Job,Project,Product,Quantity,Estimate,Stage,City,Example',...data.map(o=>[o.id,o.name,products.find(p=>p.id===o.productId)?.name,o.quantity,o.total,o.status,o.city,o.example?'Yes':'No'].map(s=>'"'+String(s).replaceAll('"','""')+'"').join(','))].join('\n'),'presswerk-production.csv','text/csv');return <main className="workspace-page production-page"><PageIntro eyebrow="FROM ARTWORK TO ARRIVAL" title="Keep the work moving." description="Plan jobs, review specifications and move each project through production."><button className="btn secondary" onClick={exportJobs}><Download size={16}/>Export board</button></PageIntro><div className="planning-banner"><span><ClipboardList size={18}/>Production planning <strong>Not connected to live equipment or carriers</strong></span><label className="switch-label"><Switch checked={examples} onCheckedChange={setExamples}/>Show example jobs</label></div><div className="stat-grid production-stats"><div><span>On the board</span><strong>{data.length.toString().padStart(2,'0')}</strong><small>{data.filter(o=>o.example).length} examples · {data.filter(o=>!o.example).length} draft jobs</small></div><div><span>Awaiting artwork review</span><strong>{data.filter(o=>o.status==='Artwork review').length.toString().padStart(2,'0')}</strong><small>Approval required before production</small></div><div><span>In production / finishing</span><strong>{data.filter(o=>['Printing','Finishing'].includes(o.status)).length.toString().padStart(2,'0')}</strong><small>Planning stages, updated manually</small></div><div><span>Estimated product value</span><strong>{money(data.reduce((s,o)=>s+o.total,0))}</strong><small>Includes examples when enabled</small></div></div><div className="board-toolbar"><div className="search-field short"><Search size={17}/><input aria-label="Search production jobs" placeholder="Find a job or project…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="row"><Pick label="Filter location" value={city} onChange={setCity} options={['All locations','Calgary','St. John’s','Other Canadian city']}/><Tabs value={layout} onValueChange={setLayout}><TabsList><TabsTrigger value="board"><Grid2X2 size={15}/>Board</TabsTrigger><TabsTrigger value="list"><ClipboardList size={15}/>List</TabsTrigger></TabsList></Tabs></div></div>{layout==='board'?<div className="kanban">{statuses.map((s,idx)=><section className="kanban-column" key={s} onDragOver={e=>e.preventDefault()} onDrop={e=>{const id=e.dataTransfer.getData('text/plain');if(data.some(o=>o.id===id))update(id,s);}}><div className="column-title"><span className={'stage-dot stage-'+idx}/><h3>{s}</h3><span>{data.filter(o=>o.status===s).length}</span></div>{data.filter(o=>o.status===s).map(o=><button className="job-card" key={o.id} draggable onDragStart={e=>e.dataTransfer.setData('text/plain',o.id)} onClick={()=>setSelected(o)}><div><span className="job-id">{o.id}</span><MoreHorizontal size={16}/></div><h4>{o.name}</h4><p>{products.find(p=>p.id===o.productId)?.name}</p><div className="job-quantity"><Package size={15}/>{o.quantity} units <span>{money(o.total)}</span></div><div className="job-bottom"><span><MapPin size={12}/>{o.city}</span><Chip color={o.example?'':'blue'}>{o.example?'Example':'Draft'}</Chip></div></button>)}{data.filter(o=>o.status===s).length===0&&<div className="column-empty"><Plus size={18}/><span>Drop a job here</span></div>}</section>)}</div>:<Table><TableHeader><TableRow>{['Job','Project','Quantity','Estimate','Stage','Location'].map(h=><TableHead key={h}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{data.map(o=><TableRow key={o.id} onClick={()=>setSelected(o)} className="click-row"><TableCell>{o.id}</TableCell><TableCell>{o.name}</TableCell><TableCell>{o.quantity}</TableCell><TableCell>{money(o.total)}</TableCell><TableCell><Chip>{o.status}</Chip></TableCell><TableCell>{o.city}</TableCell></TableRow>)}</TableBody></Table>}<p className="fineprint board-note">Move jobs to the next stage after proof approval. Workspace permissions control who can release production; each change is recorded.</p><Sheet open={!!selected} onOpenChange={open=>!open&&setSelected(null)}><SheetContent><SheetHeader><SheetTitle>{selected?.name}</SheetTitle><SheetDescription>{selected?.id} · {selected?.example?'Example production job':'Draft production plan'}</SheetDescription></SheetHeader>{selected&&<div className="sheet-body"><ProductImage p={products.find(p=>p.id===selected.productId)!}/><div className="detail-list"><div><span>Product</span><strong>{products.find(p=>p.id===selected.productId)?.name}</strong></div><div><span>Quantity</span><strong>{selected.quantity}</strong></div><div><span>Product estimate</span><strong>{money(selected.total)}</strong></div><div><span>Destination</span><strong>{selected.city}</strong></div></div>{!selected.example&&<button className="btn primary full" onClick={()=>{openRevision(selected);setSelected(null);}}><FileCheck2 size={16}/>Review saved artwork · v{selected.version}</button>}<label>Production stage<Pick value={selected.status} options={statuses} label="Change job stage" onChange={status=>update(selected.id,status)}/></label>{history.length>0&&<div className="order-history"><h4>Job history</h4>{history.map(e=><p key={e.id}><strong>{e.to_status}</strong><small>{new Date(e.created_at).toLocaleString()}</small></p>)}</div>}<h4 className="panel-subhead">Before you release the job</h4><ul className="proof-checks"><li><FileCheck2/>Approve artwork and spelling</li><li><Layers/>Confirm materials and finishing</li><li><Truck/>Confirm production and delivery dates</li><li><CheckCircle2/>Obtain customer authorization</li></ul><button className="btn secondary full" onClick={()=>download(JSON.stringify(selected,null,2),selected.id+'-job-ticket.json')}><Download size={16}/>Export job ticket</button></div>}</SheetContent></Sheet></main>;}

function Pricing({openProduct}:{openProduct:(id:string)=>void}){const [price,setPrice]=useState(29.95);const [production,setProduction]=useState(12.5);const [shipping,setShipping]=useState(11.29);const [minutes,setMinutes]=useState(6);const [labour,setLabour]=useState(30);const [margin,setMargin]=useState(40);const [acquisition,setAcquisition]=useState(0);const [remakes,setRemakes]=useState(3);const [fee,setFee]=useState(2.9);const [fixed,setFixed]=useState(.3);const [charge,setCharge]=useState(0);const [tab,setTab]=useState('economics');const nonPayment=production+shipping+minutes/60*labour+(production+shipping)*remakes/100+acquisition;const revenue=price+charge;const fees=revenue*fee/100+fixed;const contribution=revenue-nonPayment-fees;const actualMargin=revenue?contribution/revenue*100:0;const divisor=1-margin/100-fee/100;const floor=divisor>0?(nonPayment+fixed)/divisor:0;return <main className="workspace-page"><PageIntro eyebrow="PRICE WITH A PURPOSE" title="Make every job add up." description="Understand the market, protect your margin and give customers a clear choice."/><Tabs value={tab} onValueChange={setTab}><TabsList className="page-tabs" variant="line"><TabsTrigger value="economics">Order economics</TabsTrigger><TabsTrigger value="market">Market benchmarks</TabsTrigger><TabsTrigger value="tiers">Service tiers</TabsTrigger></TabsList><TabsContent value="economics"><div className="pricing-layout"><section className="form-panel"><div className="panel-heading"><span className="eyebrow">BUILD YOUR COST PICTURE</span><h2>What goes into the job?</h2><p>Editable illustration: one printed T-shirt.</p></div><div className="input-grid">{[['Selling price',price,setPrice,'$'],['Shipping charged',charge,setCharge,'$'],['Production cost',production,setProduction,'$'],['Carrier cost',shipping,setShipping,'$'],['Support / labour',minutes,setMinutes,'min'],['Loaded hourly cost',labour,setLabour,'$/h'],['Acquisition cost',acquisition,setAcquisition,'$'],['Remake allowance',remakes,setRemakes,'%'],['Payment percentage',fee,setFee,'%'],['Fixed payment fee',fixed,setFixed,'$']].map(([label,v,set,unit])=><label key={String(label)}>{String(label)}<div className="unit-input"><input type="number" min={0} step="0.1" value={v as number} onChange={e=>(set as (n:number)=>void)(Math.max(0,Number(e.target.value)))}/><span>{String(unit)}</span></div></label>)}</div><label className="margin-slider">Target contribution margin <strong>{margin}%</strong><Slider aria-label="Target contribution margin" min={5} max={80} step={1} value={[margin]} onValueChange={v=>setMargin(v[0])}/></label><p className="fineprint">Contribution is before rent, equipment payments, salaried overhead and income tax. Payment assumptions and remake rates are editable planning inputs.</p></section><section className="economics-result"><span className="eyebrow">YOUR ORDER ECONOMICS</span><h2>{money(contribution)}</h2><p>Contribution per order</p><Chip color={actualMargin>=margin?'lime':'amber'}>{actualMargin.toFixed(1)}% margin · {actualMargin>=margin?'At target':'Below your target'}</Chip><div className="cost-waterfall">{[['Production',production],['Shipping',shipping],['Labour & support',minutes/60*labour],['Remakes & acquisition',(production+shipping)*remakes/100+acquisition],['Payment fees',fees]].map(([l,n])=><div key={String(l)}><div><span>{String(l)}</span><strong>{money(n as number)}</strong></div><Progress value={Math.min(100,(n as number)/Math.max(1,revenue)*100)}/></div>)}</div><div className="price-floor"><span>Revenue needed at {margin}% margin</span><strong>{divisor>0?money(floor):'Check margin / fee'}</strong><small>Product price: {divisor>0?money(Math.max(0,floor-charge)):'Unavailable'} + {money(charge)} shipping charged</small></div><button className="btn white full" onClick={()=>download(JSON.stringify({type:'Order economics illustration',inputs:{price,production,shipping,minutes,labour,margin,acquisition,remakes,fee,fixed,charge},results:{revenue,nonPayment,fees,contribution,margin:actualMargin,requiredRevenue:floor}},null,2),'presswerk-job-economics.json')}><Download size={16}/>Export calculation</button></section></div></TabsContent><TabsContent value="market"><div className="market-note"><Info size={19}/><p>Observed September 11, 2026 · CAD · Product prices before tax and delivery unless noted. Specifications differ. Proposed Avalon Print prices require production cost validation.</p></div><div className="table-panel"><Table><TableHeader><TableRow>{['Product / quantity','Competitor','Observed price','Proposed price','Comparison limit','Source'].map(h=><TableHead key={h}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{competitorRows.map((r,i)=><TableRow key={i}><TableCell><strong>{r.product}</strong><small>{r.qty} items</small></TableCell><TableCell>{r.company}</TableCell><TableCell>{money(r.price)}</TableCell><TableCell className="blue-text">{money(r.us)}</TableCell><TableCell>{r.detail}</TableCell><TableCell><a href={r.url} target="_blank" rel="noreferrer" className="source-link">View <ExternalLink size={14}/></a></TableCell></TableRow>)}</TableBody></Table></div><div className="insight-grid"><article><h3>Compare the whole job.</h3><p>Quantity, stock, printed sides, finishing, fees and delivery must match before calling a price cheaper.</p></article><article><h3>Shipping changes the economics.</h3><p>The illustrated Printful T-shirt starts at $12.50 plus Canada shipping from $11.29. Confirm the actual destination and variant.</p><a className="source-link" href="https://www.printful.com/custom/collections/bestsellers/unisex-classic-tee-gildan-5000" target="_blank" rel="noreferrer">Source <ExternalLink size={14}/></a></article></div></TabsContent><TabsContent value="tiers"><div className="tier-grid">{[{name:'Value',sub:'For print-ready ideas.',icon:Package,points:['Standard materials and sizes','Live editor and basic file checks','Regular scheduled production','Delivery priced separately']},{name:'Design Plus',sub:'A little expert attention.',icon:Sparkles,points:['Defined artwork assistance','Agreed revisions and proof review','Specified material upgrades','Additional design work quoted']},{name:'Priority',sub:'When timing matters.',icon:Clock,points:['An earlier available production slot','Approved artwork required','Local capacity confirmation','Express delivery quoted separately']}].map((t,i)=><article key={t.name} className={i===1?'featured-tier':''}><t.icon size={27}/><span className="eyebrow">{i===1?'WITH A HUMAN TOUCH':'CHOOSE YOUR SERVICE'}</span><h2>{t.name}</h2><p>{t.sub}</p><ul>{t.points.map(s=><li key={s}><Check size={16}/>{s}</li>)}</ul><button className={'btn full '+(i===1?'white':'secondary')} onClick={()=>openProduct('cards')}>Configure a project <ArrowUpRight size={16}/></button></article>)}</div><p className="fineprint">Design Plus and Priority have separate cost requirements. A faster production slot is confirmed after artwork approval and does not itself guarantee carrier arrival.</p></TabsContent></Tabs></main>;}

function BrandCentre({brand,setBrand,design,setDesign,go,saveBrand,connected}:{brand:Brand;setBrand:React.Dispatch<React.SetStateAction<Brand>>;design:Design;setDesign:React.Dispatch<React.SetStateAction<Design>>;go:(v:View)=>void;saveBrand:()=>Promise<void>;connected:boolean}){return <main className="workspace-page"><PageIntro eyebrow="ONE IDENTITY. EVERY FORMAT." title="This is your signature." description="A considered brand system for everything you put into the world."><div className="row"><button className="btn secondary" onClick={()=>download(JSON.stringify(brand,null,2),'presswerk-brand-kit.json')}><Download size={16}/>Export brand kit</button><button className="btn primary" onClick={saveBrand}><Save size={16}/>Save brand kit</button></div></PageIntro><div className="brand-layout"><section className="brand-controls form-panel"><h3>Brand essentials</h3><label>Brand name<input value={brand.name} maxLength={60} onChange={e=>setBrand(b=>({...b,name:e.target.value}))}/></label><label>Signature line<input value={brand.tagline} maxLength={100} onChange={e=>setBrand(b=>({...b,tagline:e.target.value}))}/></label><label>Brand typeface<Pick value={brand.font} label="Brand typeface" options={['Arial','Georgia','Verdana','Courier New']} onChange={font=>setBrand(b=>({...b,font}))}/></label><h3>Colour palette</h3>{(['primary','secondary','accent'] as const).map(k=><label className="brand-color-input" key={k}><input type="color" value={brand[k]} onChange={e=>setBrand(b=>({...b,[k]:e.target.value}))}/><span>{k}<strong>{brand[k].toUpperCase()}</strong></span><button className="icon-button" aria-label={'Copy '+k+' colour'} onClick={()=>navigator.clipboard.writeText(brand[k]).then(()=>toast.success('Colour copied')).catch(()=>toast.error('Clipboard unavailable'))}><Copy size={16}/></button></label>)}<button className="btn primary full" onClick={()=>{setDesign(d=>({...d,background:brand.primary,layers:d.layers.map((l,i)=>l.type==='text'?{...l,text:i===0?brand.tagline:l.text,font:brand.font,color:'#ffffff'}:l)}));go('studio');toast.success('Brand applied to your active design');}}>Apply to active project <ArrowUpRight size={16}/></button></section><section className="brand-preview"><div className="brand-specimen" style={{background:brand.primary,color:'#ffffff',fontFamily:brand.font}}><span>THE BRAND SYSTEM / 01</span><strong>{brand.name}</strong><p>{brand.tagline}</p><span className="brand-big-symbol">✳</span></div><div className="brand-preview-bottom"><div style={{background:brand.secondary,color:'#fff',fontFamily:brand.font}}><span>YOUR TYPE, YOUR VOICE</span><strong>Aa Bb Cc<br/>0123456789</strong><small>{brand.font}</small></div><div style={{background:brand.accent,color:'#171719'}}><span>A COLOUR WITH CHARACTER</span><strong>{brand.accent.toUpperCase()}</strong><small>Accent / screen RGB</small></div></div><p className="fineprint">Save your brand kit to share a consistent identity across your workspace. Confirm colour profiles and spot colours with your print supplier.</p></section></div></main>;}

function Network(){const [category,setCategory]=useState('All capabilities');const [city,setCity]=useState('All locations');const [target,setTarget]=useState<typeof suppliers[0]|null>(null);const [brief,setBrief]=useState('');const [quantity,setQuantity]=useState(500);const [product,setProduct]=useState('Business cards');const list=suppliers.filter(s=>(category==='All capabilities'||s.tags.includes(category))&&(city==='All locations'||s.city.includes(city)));const rfq=()=>{download(`REQUEST FOR QUOTATION\nTo: ${target?.name}\nProduct: ${product}\nQuantity: ${quantity}\n\nBrief:\n${brief}\n\nPlease itemize:\n- Exact stock and printed sides\n- Production method and finishing\n- Proof / artwork charges\n- Total product price in CAD\n- Delivery to Calgary and St. John's separately\n- Taxes, lead times and quote expiry\n- Remake and quality terms\n\nNo order authorization is implied by this request.`, 'presswerk-supplier-rfq.txt','text/plain');toast.success('RFQ downloaded. Nothing has been sent.');};return <main className="workspace-page"><PageIntro eyebrow="THE RIGHT CAPABILITY. THE RIGHT JOB." title="Build your print network." description="Compare sourcing candidates and prepare consistent quote requests."/><div className="network-banner"><Globe size={35}/><div><h3>One platform. A world of possibilities.</h3><p>Local production where it makes sense. Specialist partners where it matters.</p></div><Chip color="blue">Research shortlist</Chip></div><div className="board-toolbar"><div className="row"><Pick label="Supplier capability" value={category} onChange={setCategory} options={['All capabilities',...categories.slice(1)]}/><Pick label="Supplier location" value={city} onChange={setCity} options={['All locations','Calgary','St. John’s']}/></div><span className="muted">{list.length} sourcing candidates</span></div><div className="supplier-grid">{list.map((s,i)=><article className="supplier-card" key={s.name}><div className="supplier-top"><span className={'supplier-monogram supplier-'+i}>{s.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><a href={s.url} target="_blank" rel="noreferrer" className="icon-button" aria-label={'Visit '+s.name}><ArrowUpRight size={19}/></a></div><Chip>{s.status}</Chip><h2>{s.name}</h2><span className="supplier-city"><MapPin size={14}/>{s.city}</span><p>{s.note}</p><div className="tag-list">{s.tags.map(t=><span key={t}>{t}</span>)}</div><button className="btn secondary full" onClick={()=>setTarget(s)}>Prepare quote request <ArrowRight size={16}/></button></article>)}</div>{!list.length&&<div className="empty-state"><Globe/><h3>No shortlisted suppliers match.</h3><button className="btn secondary" onClick={()=>{setCategory('All capabilities');setCity('All locations');}}>Reset filters</button></div>}<p className="fineprint">These companies are research candidates, not contracted or connected production partners. Availability, trade eligibility and destination-specific charges require verification.</p><Dialog open={!!target} onOpenChange={o=>!o&&setTarget(null)}><DialogContent><DialogHeader><DialogTitle>Prepare an RFQ</DialogTitle><DialogDescription>For {target?.name}. Download a complete request to review and send yourself.</DialogDescription></DialogHeader><label>Product<input value={product} onChange={e=>setProduct(e.target.value)}/></label><label>Quantity<input type="number" value={quantity} min={1} onChange={e=>setQuantity(Math.max(1,Math.round(Number(e.target.value))))}/></label><label>Specifications and requirements<textarea rows={6} value={brief} onChange={e=>setBrief(e.target.value)} placeholder="Dimensions, paper weight, colours, sides, finish, delivery address and required date…"/></label><button className="btn primary full" onClick={rfq} disabled={brief.length<10}><Download size={16}/>Download request</button></DialogContent></Dialog></main>;}

function Developers(){const [productId,setProductId]=useState('cards');const [qty,setQty]=useState(500);const [tier,setTier]=useState<Tier>('Value');const [response,setResponse]=useState('');const [loading,setLoading]=useState(false);const [tab,setTab]=useState('playground');const body={productId,quantity:qty,tier,finish:'Standard',sides:1,city:'Calgary',shipping:0};const run=async()=>{setLoading(true);try{const r=await fetch('/api/print/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error('API unavailable');const j=await r.json();setResponse(JSON.stringify(j,null,2));}catch{setResponse(JSON.stringify({...calculateQuote(body),execution:'Browser SDK · server API unavailable'},null,2));}setLoading(false);};const code=`const quote = await fetch('/api/print/quote', {\n  method: 'POST',\n  headers: { 'Content-Type': 'application/json' },\n  body: JSON.stringify(${JSON.stringify(body,null,2).replaceAll('\n','\n  ')})\n});\nconst estimate = await quote.json();`;return <main className="workspace-page developers-page"><PageIntro eyebrow="THE PRINT PLATFORM, PROGRAMMABLE" title="Bring print into your world." description="A shared catalogue and quote engine for storefronts, internal tools and future partner integrations."/><div className="developer-hero"><Code2 size={36}/><div><h2>From product to estimate.<br/>One request.</h2><p>Structured specifications. Validated quantities. Consistent price calculations.</p></div><span className="api-version">API / V1</span></div><Tabs value={tab} onValueChange={setTab}><TabsList className="page-tabs" variant="line"><TabsTrigger value="playground">API playground</TabsTrigger><TabsTrigger value="catalogue">Catalogue export</TabsTrigger><TabsTrigger value="integrations">Connections</TabsTrigger></TabsList><TabsContent value="playground"><div className="api-layout"><div className="form-panel"><Chip color="blue">POST /api/print/quote</Chip><h3>Try a real calculation.</h3><label>Product<Select value={productId} onValueChange={v=>{setProductId(v);setQty(products.find(p=>p.id===v)!.quantity);}}><SelectTrigger className="pw-select"><SelectValue/></SelectTrigger><SelectContent>{products.map(p=><SelectItem value={p.id} key={p.id}>{p.name}</SelectItem>)}</SelectContent></Select></label><label>Quantity<input type="number" min={1} max={100000} value={qty} onChange={e=>setQty(Math.min(100000,Math.max(1,Math.round(Number(e.target.value)))))}/></label><label>Service<Pick label="API service tier" value={tier} onChange={v=>setTier(v as Tier)} options={['Value','Design Plus','Priority']}/></label><button className="btn primary full" onClick={run} disabled={loading}><Play size={15}/>{loading?'Calculating…':'Run request'}</button><p className="fineprint">This endpoint calculates non-binding estimates. It does not create orders, collect payments or reserve production.</p></div><div className="api-code"><div><span>{response?'RESPONSE / JSON':'REQUEST / JAVASCRIPT'}</span><button onClick={()=>navigator.clipboard.writeText(response||code).then(()=>toast.success('Copied')).catch(()=>toast.error('Clipboard unavailable'))}><Copy size={15}/>Copy</button></div><pre>{response||code}</pre>{response&&<button className="text-button" onClick={()=>setResponse('')}>Show request</button>}</div></div></TabsContent><TabsContent value="catalogue"><div className="export-panel"><Package size={38}/><h2>A structured catalogue.<br/>Ready for your next application.</h2><p>{products.length} product definitions with dimensions, methods, material specifications, planning phases and price status.</p><div className="row"><button className="btn primary" onClick={()=>download(JSON.stringify({version:'1.0',currency:'CAD',priceStatus:'Proposed launch estimates',products},null,2),'presswerk-catalogue.json')}><Download size={16}/>Download JSON catalogue</button><a className="btn secondary" href="/api/print/catalogue" target="_blank" rel="noreferrer">Open catalogue API <ArrowUpRight size={16}/></a></div></div></TabsContent><TabsContent value="integrations"><div className="integration-grid">{[['AI design assistant','Model provider credentials required','Generative advice, copy and structured design suggestions',Sparkles],['Cloud workspace','Database and identity setup required','Projects, approvals, brand kits and account isolation',FolderOpen],['Payments','Merchant account setup required','Taxes, checkout, refunds and payment confirmation',ShoppingBag],['Production partners','Supplier agreements and API credentials required','Live product availability, order submission and tracking',Truck]].map(([name,status,desc,Icon])=>{const I=Icon as React.ElementType;return <article key={String(name)}><I size={24}/><h3>{String(name)}</h3><Chip color="amber">Setup required</Chip><p>{String(desc)}</p><small>{String(status)}</small></article>;})}</div></TabsContent></Tabs></main>;}

function Roadmap(){const [phase,setPhase]=useState('All phases');const phases=[{n:1,time:'MONTHS 01–03',name:'A strong first impression.',copy:'Validate everyday demand, build the quoting workflow and establish quality standards.',steps:['Launch core paper, apparel and gift estimates','Obtain three matched supplier quotes per family','Test samples, finishing time and remakes','Pilot Value and Design Plus offers']},{n:2,time:'MONTHS 04–06',name:'Make more possible.',copy:'Expand proven categories and bring repeatable work closer to home.',steps:['Add signage, labels and packaging partners','Choose equipment against measured demand','Introduce qualified local Priority slots','Standardize brand and proof approval workflows']},{n:3,time:'MONTHS 07–09',name:'Connect the operation.',copy:'Develop specialist capacity with clear quality and delivery commitments.',steps:['Pilot installation and interior graphics','Add books, textile and technical workflows','Connect verified supplier availability and tracking','Introduce recurring business account orders']},{n:4,time:'MONTHS 10–12',name:'Build for the next scale.',copy:'Strengthen systems before extending the production network.',steps:['Audit contribution and capacity by product','Complete customer identity and payment systems','Pilot external developer integrations','Review specialist and industrial project demand']}];return <main className="workspace-page"><PageIntro eyebrow="THE FIRST YEAR, INTENTIONALLY BUILT" title="Start focused. Grow connected." description="A phased operating plan for a broad printing business, with Calgary and St. John’s as launch candidates."/><div className="roadmap-grid">{phases.map(p=><article key={p.n}><div><span className="roadmap-number">0{p.n}</span><span className="eyebrow">{p.time}</span></div><h2>{p.name}</h2><p>{p.copy}</p><ul>{p.steps.map(s=><li key={s}><Circle size={13}/>{s}</li>)}</ul></article>)}</div><div className="section-title"><h2>Catalogue by launch phase</h2><Pick value={phase} onChange={setPhase} options={['All phases','Phase 1','Phase 2','Phase 3','Phase 4']} label="Filter launch phase"/></div><div className="phase-products">{products.filter(p=>phase==='All phases'||p.phase===Number(phase.slice(-1))).map(p=><div key={p.id}><span>{p.name}</span><Chip>Phase {p.phase}</Chip><small>{p.method}</small></div>)}</div><p className="fineprint">This is a proposed sequence, not an equipment purchase commitment or a forecast. Expansion depends on demand, supplier qualification and actual unit economics.</p></main>;}
